def read_number(prompt):
    while True:
        try:
            return float(input(prompt))
        except ValueError:
            pass

def read_two_numbers():
    a = read_number("Enter the first number: ")
    b = read_number("Enter the second number: ")
    return (a, b)

def divide(a, b):
    if b == 0:
        raise ZeroDivisionError("Cannot divide by zero")
    return a / b

def read_operator(OPS):
    while True:
        operator = input(f"Enter operator ({', '.join(sorted(OPS.keys()))}): ")
        if operator in OPS:
            return operator
        print("Invalid operator. Please try again.")

def apply_operation(op, a, b):
    if op not in OPS:
        raise KeyError(f"Operation '{op}' is not registered")
    return OPS[op](a, b)

def main():
    register_ops()
    try:
        a, b = read_two_numbers()
        op = read_operator(OPS)
        result = apply_operation(op, a, b)
        print(f"Result: {result}")
    except ZeroDivisionError:
        print("Error: Division by zero is not allowed.")
